generator_scripts.cohort_gen_b.py:
"""Generate single-construct removal variants for the collapsed-unit cohort.
Each variant = the main checkout's verified generated unit with ONE edited TU block substituted
verbatim. Writes OUT/<unit-id>/<owner>__<variant>.c and OUT/manifest.json."""
import json, re, sys, collections
from pathlib import Path

S = Path(sys.argv[1])
OUT = S / "cohort3"
MAIN = Path("/home/armandofm/projects/fzgx")
cohort = json.load(open(S / "cohort_b.json"))
units = json.load(open(MAIN / "config/GFZE01/units.json"))
by_src = {u["source"]: u for u in units}

PRAGMA = re.compile(r"^[ \t]*#pragma[ \t]+(\w+)[ \t]+(off|on)\b[^\n]*\n", re.M)
CARRIER = re.compile(r"struct \{ (\w[\w \t*]*?) ?value; \} (\w+);")
WARN = re.compile(r"^[ \t]*/\* WARNING: compiler-diff device[^\n]*\*/[ \t]*\n", re.M)


def block(tu_text, name):
    m = re.search(r"^/\* fzgx:begin %s(?: [^*]*)? \*/\n" % re.escape(name), tu_text, re.M)
    if not m:
        raise ValueError(name)
    i = m.end()
    return tu_text[i:tu_text.index(f"/* fzgx:end {name} */", i)]


def pseudo_block(text, name):
    """Definition of `name` in a marker-less TU, with the contiguous pragma/comment lines just
    before it and the contiguous pragma lines just after its closing brace."""
    m = re.search(r"^[A-Za-z_][^;\n]*\b%s\([^;{]*\)\s*\{[ \t]*$" % re.escape(name), text, re.M)
    if not m:
        return None
    start = m.start()
    while True:
        prev = text.rfind("\n", 0, start - 1) + 1
        line = text[prev:start]
        if prev < start and (line.lstrip().startswith("#pragma") or line.lstrip().startswith("/* WARNING")):
            start = prev
        else:
            break
    end = text.index("\n}\n", m.end()) + 3
    while True:
        nl = text.find("\n", end)
        line = text[end:nl + 1]
        if line.lstrip().startswith("#pragma") and "section" not in line:
            end = nl + 1
        else:
            break
    return text[start:end]


def drop_pragma(text, m):
    """Remove pragma match m and its first following `#pragma NAME reset` (if any)."""
    name = m.group(1)
    t = text[:m.start()] + text[m.end():]
    r = re.compile(r"^[ \t]*#pragma[ \t]+%s[ \t]+reset\b[^\n]*\n" % name, re.M)
    rm = r.search(t, m.start())
    if rm:
        t = t[:rm.start()] + t[rm.end():]
    return t


def drop_carrier(text, m):
    typ, var = m.group(1), m.group(2)
    t = text[:m.start()] + f"{typ} {var};" + text[m.end():]
    return re.sub(r"\b%s\.value\b" % re.escape(var), var, t)


def main():
    owners = collections.OrderedDict()
    for f in cohort:
        owners.setdefault((f["unit"], f["owner"], f["path"]), []).append(f)
    manifest = []
    for (unit_src, owner, path), fs in owners.items():
        name = owner.split(":", 1)[1]
        tu = (MAIN / path).read_text()
        try:
            blk = block(tu, name)
        except ValueError:
            blk = pseudo_block(tu, name)
            print("pseudo-block:", owner)
            if blk is None:
                manifest.append({"owner": owner, "unit": unit_src, "error": "definition not found in " + path})
                continue
        gp = MAIN / "build/GFZE01/gen" / unit_src
        gen = (gp if gp.exists() else MAIN / "src" / unit_src).read_text()
        if gen.count(blk) != 1:
            manifest.append({"owner": owner, "unit": unit_src, "error": f"block occurs {gen.count(blk)}x in gen"})
            continue
        variants = {}
        pms = list(PRAGMA.finditer(blk))
        for k, m in enumerate(pms):
            variants[f"p{k}_{m.group(1)}"] = drop_pragma(blk, m)
        cms = list(CARRIER.finditer(blk))
        for k, m in enumerate(cms):
            variants[f"c{k}_{m.group(2)}"] = drop_carrier(blk, m)
        if any(f["category"] == "marked-warning" for f in fs):
            for k, m in enumerate(re.finditer(r"\bvolatile\s+", blk)):
                variants[f"v{k}_volatile"] = blk[:m.start()] + blk[m.end():]
        if len(pms) + len(cms) > 1:
            t = blk
            while True:
                m = PRAGMA.search(t)
                if not m:
                    break
                t = drop_pragma(t, m)
            while True:
                m = CARRIER.search(t)
                if not m:
                    break
                t = drop_carrier(t, m)
            variants["all"] = t
        d = OUT / unit_src.replace("/", "__")
        d.mkdir(parents=True, exist_ok=True)
        for vk, vb in variants.items():
            assert vb != blk, (owner, vk)
            p = d / f"{name}__{vk}.c"
            p.write_text(gen.replace(blk, vb))
            manifest.append({"owner": owner, "unit": unit_src, "variant": vk, "file": str(p),
                             "mw": by_src[unit_src].get("mw_version") or "GC/1.3.2"})
    json.dump(manifest, open(OUT / "manifest.json", "w"), indent=1)
    print(len(manifest), "entries;", sum(1 for m in manifest if "error" in m), "errors")
    for m in manifest:
        if "error" in m:
            print(m)


main()

generator_scripts.cohort_run_b.py:
"""Compile every cohort variant with its unit's exact ninja command (compiler, flags, poolfix)
and objdiff it against the main checkout's hash-verified unit object.
A per-unit control (the unmodified verified gen file) must MATCH or the unit is skipped.
usage: cohort_run.py SCRATCH   (run from the worktree root)"""
import json, shlex, subprocess, sys, collections
from concurrent.futures import ThreadPoolExecutor
from pathlib import Path

S = Path(sys.argv[1])
MAIN = Path("/home/armandofm/projects/fzgx")
OBJDIFF = Path("build/tools/objdiff-cli")
man = [m for m in json.load(open(S / "cohort3/manifest.json")) if "file" in m]
OBJ = S / "cohort3_obj"
OBJ.mkdir(exist_ok=True)


def unit_obj(unit_src):
    return "build/GFZE01/src/" + unit_src[:-2] + ".o"


_cmds = {}


def command(unit_src):
    if unit_src not in _cmds:
        cp = subprocess.run(["ninja", "-t", "commands", "-s", unit_obj(unit_src)], cwd=MAIN,
                            text=True, capture_output=True, check=True)
        _cmds[unit_src] = cp.stdout.strip().splitlines()[-1]
    return _cmds[unit_src]


def compile_variant(unit_src, src, out):
    cmd = command(unit_src)
    gen = "build/GFZE01/gen/" + unit_src
    if not (MAIN / gen).exists():
        gen = "src/" + unit_src
    if cmd.startswith("sh tools/mwcc_batch.sh"):
        cc = shlex.split(cmd.split(" -- ", 1)[1])
        steps = [cc + ["-c", str(src), "-o", str(out)]]
    else:
        parts = cmd.split(" && ")
        cc = [a for a in shlex.split(parts[0]) if a != "-MMD"]
        i = cc.index("-c")
        assert cc[i + 1] == gen, (cc[i + 1], gen)
        cc[i + 1] = str(src)
        cc[cc.index("-o") + 1] = str(out)
        steps = [cc]
        for p in parts[1:]:
            a = shlex.split(p)
            if "tools/fzgx/poolfix.py" in a:
                a[a.index("tools/fzgx/poolfix.py") + 1] = str(out)
                steps.append(a)
            elif "transform_dep.py" in p:
                continue
            else:
                raise RuntimeError("unknown step: " + p)
    for k, st in enumerate(steps):
        cp = subprocess.run(st, text=True, capture_output=True)
        if cp.returncode != 0:
            return ("POOLSTALE " if k > 0 else "") + (cp.stdout + cp.stderr)[-800:]
    return None


def diff(unit_src, obj):
    ref = MAIN / unit_obj(unit_src)
    cp = subprocess.run([str(OBJDIFF), "diff", "-1", str(ref), "-2", str(obj), "-o", "-", "--format", "json"],
                        text=True, capture_output=True)
    d = json.loads(cp.stdout)
    bad = {}
    for kind in ("symbols", "sections"):
        for s in d.get("left", {}).get(kind, []):
            mp = s.get("match_percent")
            if mp is not None and mp < 100.0:
                bad[s["name"]] = round(mp, 3)
    return bad


def run(m, tag):
    out = OBJ / (Path(m["file"]).parent.name + "__" + Path(m["file"]).stem + ".o")
    err = compile_variant(m["unit"], m["file"], out)
    if err and err.startswith("POOLSTALE"):
        sys.path.insert(0, "tools")
        from fzgx import oracle
        name = m["owner"].split(":", 1)[1]
        ref = oracle.words(MAIN / unit_obj(m["unit"]), name)
        ours = oracle.words(out, name)
        same = ref is not None and ref == ours
        return dict(m, verdict="POOL-WORDS-SAME" if same else "POOL-WORDS-DIFF",
                    detail="" if same else (oracle.word_score(ref or [], ours or [])[0]))
    if err:
        return dict(m, verdict="compile-error", detail=err)
    bad = diff(m["unit"], out)
    return dict(m, verdict="MATCH" if not bad else "DIFF", detail=bad)


def main():
    unitset = sorted({m["unit"] for m in man})
    controls = {}
    for u in unitset:
        c = S / "cohort3" / u.replace("/", "__") / "_control.c"
        gp = MAIN / "build/GFZE01/gen" / u
        c.write_text((gp if gp.exists() else MAIN / "src" / u).read_text())
        r = run({"unit": u, "file": str(c), "owner": "control", "variant": "control"}, "control")
        controls[u] = r["verdict"]
        print("control", u, r["verdict"], r["detail"] if r["verdict"] != "MATCH" else "")
    todo = [m for m in man if controls[m["unit"]] == "MATCH"]
    with ThreadPoolExecutor(16) as ex:
        res = list(ex.map(lambda m: run(m, ""), todo))
    res += [dict(m, verdict="skipped-control") for m in man if controls[m["unit"]] != "MATCH"]
    json.dump({"controls": controls, "results": res}, open(S / "cohort3_results.json", "w"), indent=1)
    c = collections.Counter(r["verdict"] for r in res)
    print(c)
    for r in res:
        if r["verdict"] in ("MATCH", "POOL-WORDS-SAME"):
            print(r["verdict"], r["owner"], r["variant"])
    for r in res:
        if r["verdict"] == "POOL-WORDS-DIFF":
            print("PWDIFF", r["owner"], r["variant"], r["detail"])
        if r["verdict"] == "DIFF":
            own = r["owner"].split(":")[1]
            print("DIFF ", r["owner"], r["variant"], r["detail"].get(own, r["detail"]))


main()

